using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;

var builder = WebApplication.CreateBuilder(args);

// 注册健康检查：数据库、Redis、自定义检查
builder.Services.AddHealthChecks()
    .AddCheck("self", () => HealthCheckResult.Healthy())
    .AddSqlServer(
        builder.Configuration.GetConnectionString("DefaultConnection"),
        name: "sqlserver",
        tags: new[] { "ready" })
    .AddRedis(
        builder.Configuration["Redis:Configuration"],
        name: "redis",
        tags: new[] { "ready" })
    .AddCheck("memory", () =>
    {
        var allocated = GC.GetTotalMemory(false);
        var threshold = 512L * 1024L * 1024L;
        return allocated < threshold
            ? HealthCheckResult.Healthy($"{allocated / 1024 / 1024} MB")
            : HealthCheckResult.Unhealthy($"{allocated / 1024 / 1024} MB exceeds {threshold / 1024 / 1024} MB");
    });

var app = builder.Build();

// liveness：只检查进程是否响应，不检查依赖
app.MapHealthChecks("/health/live", new HealthCheckOptions
{
    Predicate = _ => false  // 不执行任何检查，只返回 200
});

// readiness：检查所有标记为 ready 的依赖
app.MapHealthChecks("/health/ready", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("ready"),
    ResponseWriter = UIResponseWriter.WriteHealthCheckUIResponse
});

// 优雅停机：在 SIGTERM 时完成在途请求
var lifetime = app.Services.GetRequiredService<IHostApplicationLifetime>();
lifetime.ApplicationStopping.Register(() =>
{
    Console.WriteLine("SIGTERM received, stopping gracefully...");
    // 停止消息消费者、刷新缓冲区等
});

app.MapGet("/", () => "Hello from .NET Container!");
app.Run();
